mapper.select:
SELECT id logId,scope_type scopeType,action_type actionType,project_id projectId,project_name_snapshot projectName,
    operator_user_id operatorId,operator_name_snapshot operatorName,target_user_id targetId,target_name_snapshot targetName,
    grant_type grantType,role_code roleCode,permission_code permissionCode,before_snapshot beforeSnapshot,after_snapshot afterSnapshot,remark,created_at createdAt
    FROM admin_operation_log

      AND (remark LIKE #{filter.keyword} OR project_name_snapshot LIKE #{filter.keyword})
      AND action_type=#{filter.actionType}
      AND scope_type=#{filter.scopeType}
      AND project_id=#{filter.projectId}
      AND operator_user_id=#{filter.operatorId}
      AND created_at>=#{filter.from}
      AND created_at<#{filter.to}

    ORDER BY created_at DESC LIMIT 1000
